#!/bin/bash
python3 -c $'import sys,json,math\ns=sys.argv[1] if len(sys.argv)>1 else \'1011\'\nR=json.loads(sys.argv[2]) if len(sys.argv)>2 else {\'0,0\':[0,\'0\',1],\'0,1\':[0,\'1\',1],\'0,_\':[1,\'_\',-1],\'1,1\':[1,\'0\',-1],\'1,0\':[2,\'1\',0],\'1,_\':[2,\'1\',0]}\nassert all(len(k.split(\',\'))==2 and len(v)==3 and type(v[0])==int and type(v[1])==str and len(v[1])==1 and type(v[2])==int and v[2] in (-1,0,1) for k,v in R.items())\nq=h=0;t={i:c for i,c in enumerate(s) if c!=\'_\'};hist=[]\nwhile True:\n hist.append([q,h,sorted(t.items())]);v=R.get(str(q)+\',\'+t.get(h,\'_\'))\n if v is None:break\n q,w,d=v\n if w==\'_\':t.pop(h,None)\n else:t[h]=w\n h+=d\nb=json.dumps([R,s,hist],sort_keys=True,separators=(\',\',\':\')).encode();a=1\nfor v in b:a=a*257+v+1\nz=a;back=[]\nwhile z>1:\n z,r=divmod(z,257);assert r;back.append(r-1)\nassert bytes(back[::-1])==b\np=[];k=2;g=1\nwhile len(p)<len(b):\n if all(k%d for d in p if d*d<=k):p.append(k)\n k+=1\nfor d,v in zip(p,b):g*=d**(v+1)\nz=g;back=[]\nfor d in p:\n e=0\n while z%d==0:z//=d;e+=1\n assert 1<=e<=256\n back.append(e-1)\nassert z==1 and bytes(back)==b\n# reversible XOR encoding circuit: |x>|0> -> |x>|f(x)>; then uncompute\nx=a&1;y=0;y^=x;assert y==x;y^=x;assert y==0\nphase=(-1)**((a.bit_count()+g.bit_count())%2);prob=[(1+phase)/2,(1-phase)/2]\nprint(json.dumps(dict(steps=len(hist)-1,halted=True,base257_bits=a.bit_length(),prime_bits=g.bit_length(),roundtrip=True,reversible_XOR=True,H_phase_H=prob,pure_state_entropy=0,conditional_next_entropy=0,final=hist[-1]),ensure_ascii=False))\n' "$@"